namespace RaceDay.Api.Models;
public class Event { public int EventId { get; set; } public int OrganiserId { get; set; } public string EventName { get; set; } = ""; public string? Description { get; set; } public DateTime EventDate { get; set; } public string Venue { get; set; } = ""; public string City { get; set; } = ""; public string Province { get; set; } = ""; public string EventType { get; set; } = ""; public string Status { get; set; } = "Upcoming"; public DateTime CreatedAt { get; set; } public User? Organiser { get; set; } public ICollection<EventRoute> Routes { get; set; } = new List<EventRoute>(); public ICollection<Category> Categories { get; set; } = new List<Category>(); }
